//! Generates `ids.rs` (the NTB1 id tables) from `props.json`.
//!
//! `props.json` is a byte-for-byte copy of thalora-web-browser `docs/b1-props.json`; denext
//! generates its TypeScript table from the same file. Ids are append-only: never renumber
//! here, change the source file and copy it again.

use std::collections::BTreeMap;
use std::fmt::Write as _;
use std::path::PathBuf;

/// Where `props.json` was copied from (the header of the generated file names it).
const SOURCE: &str = "thalora-web-browser `docs/b1-props.json` @ 7debb58";

fn main() {
  println!("cargo:rerun-if-changed=props.json");
  println!("cargo:rerun-if-changed=build.rs");
  let text = std::fs::read_to_string("props.json").expect("read props.json");
  let json: serde_json::Value =
    serde_json::from_str(&text).expect("props.json is JSON");

  let mut out = String::new();
  writeln!(
    out,
    "// @generated by build.rs from props.json. Do not edit."
  )
  .unwrap();
  writeln!(out, "// Source: {SOURCE}.").unwrap();
  writeln!(
    out,
    "// Ids are append-only within a version; never renumber."
  )
  .unwrap();
  writeln!(out).unwrap();
  writeln!(out, "/// Where the table was copied from.").unwrap();
  writeln!(out, "pub const SOURCE: &str = {SOURCE:?};").unwrap();
  let version = json["version"].as_u64().expect("version");
  writeln!(out, "/// The table's (and the batch format's) version.").unwrap();
  writeln!(out, "pub const VERSION: u16 = {version};").unwrap();
  writeln!(out).unwrap();

  id_enum(
    &mut out,
    "Kind",
    "A node kind (CREATE).",
    &table(&json, "kinds"),
  );
  id_enum(
    &mut out,
    "StyleProp",
    "A style prop (SET_STYLE).",
    &table(&json, "style"),
  );
  id_enum(
    &mut out,
    "Prop",
    "A non-style prop (SET_PROP).",
    &table(&json, "props"),
  );

  // Enum values, one module per enum, and which prop takes which.
  let enums = json["enums"].as_object().expect("enums");
  let style = table(&json, "style");
  let props = table(&json, "props");
  writeln!(
    out,
    "/// The enum values of the enum-valued props, by prop name."
  )
  .unwrap();
  writeln!(out, "pub mod enums {{").unwrap();
  let mut names: Vec<&String> = enums.keys().collect();
  names.sort();
  for name in &names {
    let values = by_id(enums[name.as_str()].as_object().expect("enum"));
    writeln!(out, "  /// `{name}`.").unwrap();
    writeln!(out, "  pub mod {} {{", snake(name)).unwrap();
    for (id, value) in &values {
      writeln!(out, "    pub const {}: u8 = {id};", screaming(value)).unwrap();
    }
    let ids: Vec<String> =
      values.iter().map(|(id, _)| id.to_string()).collect();
    writeln!(out, "    /// Every value, ascending.").unwrap();
    writeln!(out, "    pub const VALUES: &[u8] = &[{}];", ids.join(", "))
      .unwrap();
    let pairs: Vec<String> = values
      .iter()
      .map(|(id, value)| format!("({value:?}, {id})"))
      .collect();
    writeln!(
      out,
      "    /// Every value with its name in the source table."
    )
    .unwrap();
    writeln!(
      out,
      "    pub const NAMES: &[(&str, u8)] = &[{}];",
      pairs.join(", ")
    )
    .unwrap();
    writeln!(out, "  }}").unwrap();
  }
  writeln!(out, "}}").unwrap();
  writeln!(out).unwrap();

  for (ty, table, doc) in [
    ("StyleProp", &style, "style prop"),
    ("Prop", &props, "non-style prop"),
  ] {
    writeln!(out, "impl {ty} {{").unwrap();
    writeln!(
      out,
      "  /// The values this {doc} takes when it is enum-valued."
    )
    .unwrap();
    writeln!(
      out,
      "  pub const fn enum_values(self) -> Option<&'static [u8]> {{"
    )
    .unwrap();
    writeln!(out, "    match self {{").unwrap();
    let mut any = false;
    for (_, name) in by_id_u64(table) {
      if enums.contains_key(&name) {
        any = true;
        writeln!(
          out,
          "      {ty}::{} => Some(enums::{}::VALUES),",
          pascal(&name),
          snake(&name)
        )
        .unwrap();
      }
    }
    assert!(any, "{ty} has no enum-valued prop");
    writeln!(out, "      _ => None,").unwrap();
    writeln!(out, "    }}").unwrap();
    writeln!(out, "  }}").unwrap();
    writeln!(out, "}}").unwrap();
    writeln!(out).unwrap();
  }
  for name in &names {
    assert!(
      style.contains_key(name.as_str()) || props.contains_key(name.as_str()),
      "enum {name} belongs to no prop"
    );
  }

  writeln!(out, "/// LISTEN mask bits.").unwrap();
  writeln!(out, "pub mod listen {{").unwrap();
  let listen = by_id_u64(&table(&json, "listen"));
  let mut all = 0u64;
  for (bit, name) in &listen {
    assert!(bit.is_power_of_two(), "listen bit {name} = {bit}");
    all |= bit;
    writeln!(out, "  pub const {}: u32 = {bit};", screaming(name)).unwrap();
  }
  writeln!(out, "  /// Every bit a mask may carry.").unwrap();
  writeln!(out, "  pub const ALL: u32 = {all};").unwrap();
  writeln!(out, "}}").unwrap();

  let path = PathBuf::from(std::env::var("OUT_DIR").unwrap()).join("ids.rs");
  std::fs::write(path, out).expect("write ids.rs");
}

fn table(json: &serde_json::Value, key: &str) -> BTreeMap<String, u64> {
  json[key]
    .as_object()
    .unwrap_or_else(|| panic!("props.json has no {key} table"))
    .iter()
    .map(|(name, id)| (name.clone(), id.as_u64().expect("an id")))
    .collect()
}

fn by_id_u64(table: &BTreeMap<String, u64>) -> Vec<(u64, String)> {
  let mut entries: Vec<(u64, String)> =
    table.iter().map(|(name, id)| (*id, name.clone())).collect();
  entries.sort();
  for pair in entries.windows(2) {
    assert_ne!(pair[0].0, pair[1].0, "duplicate id {}", pair[0].0);
  }
  entries
}

fn by_id(
  object: &serde_json::Map<String, serde_json::Value>,
) -> Vec<(u64, String)> {
  by_id_u64(
    &object
      .iter()
      .map(|(name, id)| (name.clone(), id.as_u64().expect("an id")))
      .collect(),
  )
}

/// A `#[repr(u16)]` enum with `from_u16`, `name` and `ALL`.
fn id_enum(
  out: &mut String,
  ty: &str,
  doc: &str,
  table: &BTreeMap<String, u64>,
) {
  let entries = by_id_u64(table);
  writeln!(out, "/// {doc}").unwrap();
  writeln!(
    out,
    "#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord)]"
  )
  .unwrap();
  writeln!(out, "#[repr(u16)]").unwrap();
  writeln!(out, "pub enum {ty} {{").unwrap();
  for (id, name) in &entries {
    assert!(*id > 0 && *id <= u16::MAX as u64, "{ty} id {id}");
    writeln!(out, "  {} = {id},", pascal(name)).unwrap();
  }
  writeln!(out, "}}").unwrap();
  writeln!(out).unwrap();
  writeln!(out, "impl {ty} {{").unwrap();
  let all: Vec<String> = entries
    .iter()
    .map(|(_, name)| format!("{ty}::{}", pascal(name)))
    .collect();
  writeln!(out, "  /// Every id, ascending.").unwrap();
  writeln!(out, "  pub const ALL: &[{ty}] = &[{}];", all.join(", ")).unwrap();
  writeln!(out, "  pub const fn from_u16(id: u16) -> Option<Self> {{").unwrap();
  writeln!(out, "    match id {{").unwrap();
  for (id, name) in &entries {
    writeln!(out, "      {id} => Some({ty}::{}),", pascal(name)).unwrap();
  }
  writeln!(out, "      _ => None,").unwrap();
  writeln!(out, "    }}").unwrap();
  writeln!(out, "  }}").unwrap();
  writeln!(
    out,
    "  /// The name in the source table (the React Native prop name)."
  )
  .unwrap();
  writeln!(out, "  pub const fn name(self) -> &'static str {{").unwrap();
  writeln!(out, "    match self {{").unwrap();
  for (_, name) in &entries {
    writeln!(out, "      {ty}::{} => {name:?},", pascal(name)).unwrap();
  }
  writeln!(out, "    }}").unwrap();
  writeln!(out, "  }}").unwrap();
  writeln!(out, "}}").unwrap();
  writeln!(out).unwrap();
}

/// `flexDirection` -> `FlexDirection`, `testID` -> `TestId`.
fn pascal(name: &str) -> String {
  let mut out = String::new();
  let mut upper = true;
  let mut previous_upper = false;
  for c in name.chars() {
    if !c.is_ascii_alphanumeric() {
      upper = true;
      previous_upper = false;
      continue;
    }
    if upper {
      out.push(c.to_ascii_uppercase());
      upper = false;
      previous_upper = c.is_ascii_uppercase();
    } else if c.is_ascii_uppercase() && previous_upper {
      // A run of capitals (`ID`) keeps only its first.
      out.push(c.to_ascii_lowercase());
    } else {
      previous_upper = c.is_ascii_uppercase();
      out.push(c);
    }
  }
  out
}

/// `flexDirection` -> `flex_direction`.
fn snake(name: &str) -> String {
  let mut out = String::new();
  let mut previous_upper = true;
  for c in name.chars() {
    if !c.is_ascii_alphanumeric() {
      out.push('_');
      previous_upper = true;
    } else if c.is_ascii_uppercase() {
      if !previous_upper {
        out.push('_');
      }
      out.push(c.to_ascii_lowercase());
      previous_upper = true;
    } else {
      out.push(c);
      previous_upper = false;
    }
  }
  out
}

/// `row-reverse` -> `ROW_REVERSE`, `underline line-through` -> `UNDERLINE_LINE_THROUGH`.
fn screaming(name: &str) -> String {
  snake(name).to_ascii_uppercase()
}
